107,"\uc5b4\ub5a4 \ub178\ub798\uc778\uc9c0 \ud55c \uc904\ub85c \uc801\uc5b4 \uc8fc\uc138\uc694.":108,"\uc8fc\uc81c\ub294 80\uc790 \uc548\uc73c\ub85c \uc9e7\uac8c \uc801\uc5b4 \uc8fc\uc138\uc694.":109,[u.hF]:110,[u.ie]:111,[u.om]:112,"AI \uc791\uc0ac\ub294 \ud558\ub8e8 20\ubc88\uae4c\uc9c0\uc608\uc694. \ub0b4\uc77c \ub2e4\uc2dc \uc368 \uc8fc\uc138\uc694.":113,"AI \uc791\uc0ac\uac00 \uc7a0\uc2dc \uc26c\uace0 \uc788\uc5b4\uc694. \uc7a0\uc2dc \ub4a4 \ub2e4\uc2dc \ub20c\ub7ec \uc8fc\uc138\uc694.":114,"\uac00\uc0ac\uac00 \uaddc\uce59\uc5d0 \ub9de\uc9c0 \uc54a\uac8c \ub098\uc654\uc5b4\uc694. \ud55c \ubc88 \ub354 \ub20c\ub7ec \uc8fc\uc138\uc694.":115,[u.oq]:116,[u.n4]:117,[u.ee]:118,"\ub9cc\ub4e4\uae30\ub97c \uc7a0\uc2dc \uba48\ucdc4\uc5b4\uc694. \uace7 \ub2e4\uc2dc \uc5f4\uac8c\uc694.":119,"\uc774\uba54\uc77c\ub85c \ub85c\uadf8\uc778\ud574\uc57c \ub9cc\ub4e4 \uc218 \uc788\uc5b4\uc694.":120,"\uad8c\ub9ac \ubb38\uc81c\ub85c \uc5c5\ub85c\ub4dc\uac00 \uba48\ucdb0 \uc788\uc5b4\uc11c \uc9c0\uae08\uc740 \ub9cc\ub4e4 \uc218 \uc5c6\uc5b4\uc694.":121,"\uc624\ub298 \uc62c\ub9b4 \uc218 \uc788\ub294 \uace1 \uc218\ub97c \ub2e4 \uc37c\uc5b4\uc694. \ub0b4\uc77c \ub2e4\uc2dc \uc62c\ub824 \uc8fc\uc138\uc694.":122,"\ub0a8\uae38 \uad6c\uac04\uc774 60\ucd08 \uc774\uc0c1\uc774\uc5b4\uc57c \uc7ac\uc0dd\uc774 \uc9d1\uacc4\ub3fc\uc694.":123,"\uc774 \ubb36\uc74c\uc740 \uc774\ubbf8 \ud55c \ud14c\uc774\ud06c\ub97c \uc62c\ub838\uc5b4\uc694.":124,"\uc544\uc9c1 \ub2e4 \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc5b4\uc694.":125,"\ub9cc\ub4e0 \uae30\ub85d\uc744 \ucc3e\uc9c0 \ubabb\ud588\uc5b4\uc694.":126,"\uace1 \ub9cc\ub4e4\uae30 \uc694\uccad\uc774 \uc2e4\ud328\ud588\uc5b4\uc694. \uc7a0\uc2dc \ub4a4 \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694.":127,"\uc774 \ub808\uc2dc\ud53c\ub85c \ub9cc\ub4e4 \uc218 \uc788\ub294 \ubc84\uc804\uc744 \ub2e4 \ub9cc\ub4e4\uc5c8\uc5b4\uc694.":128,"\uc9c1\uc811 \uc4f4 \uac00\uc0ac\ub77c\ub294 \ub370 \ub3d9\uc758\ud574\uc57c \ub9cc\ub4e4 \uc218 \uc788\uc5b4\uc694.":129